const allItems = $input.all();
const keywords = ['هوش مصنوعی', 'اینترنت', 'فیلترینگ', 'فیلتر', 'امنیت', 'تکنولوژی', 'سایبری', 'شبکه', 'گوگل', 'متا', 'تلگرام', 'اینستاگرام', 'واتساپ'];

const filtered = allItems.filter(item => {
  const title = (item.json.title || '').toLowerCase();
  const desc = (item.json.description || '').toLowerCase();
  const combined = title + ' ' + desc;
  return keywords.some(kw => combined.includes(kw));
});

// Get top 2 matching news to avoid overloading the AI limit per run
return filtered.slice(0, 2).map(item => {
  // Sanitize control characters that break JSON parsing
  const rawTitle = (item.json.title || '').replace(/[\n\r\t"\\]/g, ' ');
  const rawDesc = (item.json.description || item.json.contentSnippet || '').replace(/[\n\r\t"\\]/g, ' ');
  return {
    json: {
      rawTitle,
      rawLink: item.json.link,
      rawDesc,
      sourceName: item.json.link.includes('digiato') ? 'دیجیاتو' : item.json.link.includes('zoomit') ? 'زومیت' : 'هوشیو'
    }
  };
});

